CREATE TABLE public.ledgers_members (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, created_by uuid NOT NULL, ledger bigint NOT NULL, member uuid NOT NULL);
ALTER TABLE public.ledgers_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ledgers_members ADD CONSTRAINT ledgers_members_created_by_fkey FOREIGN KEY (created_by) REFERENCES auth.users(id);
ALTER TABLE public.ledgers_members ADD CONSTRAINT ledgers_members_ledger_fkey FOREIGN KEY (ledger) REFERENCES public.ledgers(id);
ALTER TABLE public.ledgers_members ADD CONSTRAINT ledgers_members_member_fkey FOREIGN KEY (member) REFERENCES auth.users(id);
ALTER TABLE public.ledgers_members ADD CONSTRAINT ledgers_members_pkey PRIMARY KEY (id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.ledgers_members TO anon;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.ledgers_members TO authenticated;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.ledgers_members TO service_role;
CREATE TABLE public.organizations_members (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, created_by uuid NOT NULL, organization bigint NOT NULL, member uuid NOT NULL);
ALTER TABLE public.organizations_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organizations_members ADD CONSTRAINT organizations_members_created_by_fkey FOREIGN KEY (created_by) REFERENCES auth.users(id);
ALTER TABLE public.organizations_members ADD CONSTRAINT organizations_members_member_fkey FOREIGN KEY (member) REFERENCES auth.users(id);
ALTER TABLE public.organizations_members ADD CONSTRAINT organizations_members_organization_fkey FOREIGN KEY (organization) REFERENCES public.organizations(id);
ALTER TABLE public.organizations_members ADD CONSTRAINT organizations_members_pkey PRIMARY KEY (id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.organizations_members TO anon;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.organizations_members TO authenticated;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.organizations_members TO service_role;
